// Rota las opciones para que la respuesta correcta no esté siempre en la misma letra.
const ap = (x) => ({ es: x, pt: x, en: x });
export const PDF_EXPERTO = FILAS.map(([m, caso, q, c, d, e], i) => {
  const opciones = [c, ...d];
  const rot = i % 4;
  const rotadas = opciones.map((_, k) => opciones[(k + rot) % 4]);
  const a = rotadas.indexOf(c);
  return { m, a, ...ap({ caso, q, o: rotadas, e }) };
});
